// ─── SLIDE COMPONENT ────────────────────────────────────────────
function PhoneSlide({ s, current, total }) {
  return (
    <div style={{ width: "100%", height: "100%", background: s.refl ? C.darkMid : C.dark, display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", padding: "2rem 1.5rem", textAlign: "center", position: "relative" }}>
      {s.refl && <div style={{ fontSize: 22, color: C.gold, marginBottom: 10 }}>◈</div>}
      {!s.refl && s.badge && <div style={{ fontSize: 9, letterSpacing: "0.14em", textTransform: "uppercase", color: C.dark, background: C.gold, padding: "3px 10px", borderRadius: 20, marginBottom: 10, fontFamily: "sans-serif" }}>{s.badge}</div>}
      {s.ar && <div style={{ fontSize: 14, color: C.gold, marginBottom: 8, direction: "rtl", fontFamily: "serif", lineHeight: 1.6 }}>{s.ar}</div>}
      {s.ey && <div style={{ fontSize: 9, letterSpacing: "0.18em", textTransform: "uppercase", color: C.gold, marginBottom: 8, fontFamily: "sans-serif" }}>{s.ey}</div>}
      {s.ti && <div style={{ fontSize: 17, fontWeight: 600, color: C.cream, lineHeight: 1.35, fontFamily: "Georgia, serif", marginBottom: 8, whiteSpace: "pre-line" }}>{s.ti}</div>}
      {!s.refl && !s.ti && <div style={{ width: 28, height: 2, background: C.gold, margin: "0 auto 8px" }} />}
      {s.qt && <div style={{ fontSize: 11, color: C.slate, lineHeight: 1.8, fontStyle: "italic", fontFamily: "Georgia, serif", borderLeft: `2px solid ${C.gold}`, paddingLeft: 10, textAlign: "left" }}>{s.qt}</div>}
      {s.at && <div style={{ fontSize: 10, color: C.muted, marginTop: 6, textAlign: "left", fontFamily: "sans-serif" }}>{s.at}</div>}
      {s.bo && <div style={{ fontSize: 12, color: C.slate, lineHeight: 1.75, fontFamily: "sans-serif", whiteSpace: "pre-line" }}>{s.bo}</div>}
      {s.list && <div style={{ width: "100%", marginTop: 4 }}>{s.list.map((item, i) => <div key={i} style={{ fontSize: 11, color: C.slate, lineHeight: 1.6, textAlign: "left", padding: "3px 0", borderBottom: i < s.list.length - 1 ? `0.5px solid ${C.dim}` : "none" }}>• {item}</div>)}</div>}
      <div style={{ position: "absolute", bottom: 10, right: 14, fontSize: 9, color: C.dim, fontFamily: "sans-serif" }}>{current + 1} / {total}</div>
      <div style={{ position: "absolute", bottom: 0, left: 0, height: 2, background: C.gold, width: `${((current + 1) / total) * 100}%`, transition: "width 0.3s" }} />
    </div>
  );
}

// ─── CHAPTER VIEWER ─────────────────────────────────────────────
function ChapterViewer({ chapter }) {
  const [slide, setSlide] = useState(0);
  const [revealed, setRevealed] = useState({});
  const [scores, setScores] = useState({});
  const [tab, setTab] = useState("slides");

  const slides = chapter.slides;
  const total = slides.length;
  const correct = chapter.qa.filter((_, i) => scores[i] === true).length;
  const answered = chapter.qa.filter((_, i) => scores[i] !== undefined).length;

  return (
    <div>
      {/* Tab selector */}
      <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
        {["slides", "Q&A"].map(t => (
          <button key={t} onClick={() => setTab(t)} style={{ padding: "6px 16px", borderRadius: 20, border: `1.5px solid ${tab === t ? C.gold : "#ddd"}`, background: tab === t ? C.gold : "white", color: tab === t ? "white" : "#666", fontSize: 12, fontWeight: tab === t ? 700 : 400, cursor: "pointer" }}>{t === "slides" ? "📱 Slides" : `❓ Q&A${answered > 0 ? ` (${correct}/${chapter.qa.length})` : ""}`}</button>
        ))}
      </div>

      {tab === "slides" && (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
          <div style={{ width: 280, height: 497, borderRadius: 28, border: "2px solid #2a2a2a", overflow: "hidden" }}>
            <PhoneSlide s={slides[slide]} current={slide} total={total} />
          </div>
          <div style={{ display: "flex", gap: 4, marginTop: 10, flexWrap: "wrap", justifyContent: "center", maxWidth: 280 }}>
            {slides.map((_, i) => <div key={i} onClick={() => setSlide(i)} style={{ width: 5, height: 5, borderRadius: "50%", background: i === slide ? C.gold : "#ddd", cursor: "pointer" }} />)}
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 14, marginTop: 12 }}>
            <button onClick={() => setSlide(s => s > 0 ? s - 1 : total - 1)} style={{ width: 38, height: 38, borderRadius: "50%", border: "0.5px solid #ddd", background: "white", cursor: "pointer", fontSize: 16 }}>‹</button>
            <div style={{ fontSize: 12, color: "#aaa" }}>{slide + 1} / {total}</div>
            <button onClick={() => setSlide(s => s < total - 1 ? s + 1 : 0)} style={{ width: 38, height: 38, borderRadius: "50%", border: "0.5px solid #ddd", background: "white", cursor: "pointer", fontSize: 16 }}>›</button>
          </div>
          {slides[slide].sc && (
            <div style={{ marginTop: 16, background: "white", border: `1.5px solid ${C.border}`, borderRadius: 12, padding: "1rem 1.125rem", maxWidth: 300, width: "100%" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 8 }}>
                <div style={{ width: 3, height: 16, background: C.gold, borderRadius: 2 }} />
                <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.12em", color: C.gold }}>Slide {slide + 1} — Script</div>
              </div>
              <p style={{ fontSize: 13, color: "#333", lineHeight: 1.8, margin: 0 }}>{slides[slide].sc}</p>
            </div>
          )}
        </div>
      )}

      {tab === "Q&A" && (
        <div>
          {chapter.qa.map((item, qi) => {
            const isOpen = !!revealed[qi];
            const mark = scores[qi];
            return (
              <div key={qi} style={{ border: `1.5px solid ${isOpen ? C.gold : "#e0e0e0"}`, borderRadius: 12, marginBottom: 12, overflow: "hidden" }}>
                <div style={{ padding: "0.875rem 1rem", background: "white" }}>
                  <div style={{ display: "flex", alignItems: "flex-start", gap: 8, marginBottom: 10 }}>
                    <div style={{ width: 24, height: 24, borderRadius: "50%", background: mark === true ? C.green : mark === false ? C.red : isOpen ? C.gold : "#eee", color: "white", fontSize: 10, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginTop: 1 }}>
                      {mark === true ? "✓" : mark === false ? "✗" : qi + 1}
                    </div>
                    <div style={{ flex: 1, fontSize: 13, lineHeight: 1.55, color: "#1a1a1a", fontWeight: 500 }}>{item.q}</div>
                  </div>
                  {!isOpen && (
                    <button onClick={() => setRevealed(r => ({ ...r, [qi]: true }))} style={{ marginLeft: 32, padding: "6px 16px", borderRadius: 20, background: C.gold, color: "white", border: "none", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>▼ Reveal Answer</button>
                  )}
                </div>
                {isOpen && (
                  <div style={{ padding: "0.75rem 1rem 0.875rem", background: C.goldBg, borderTop: `1px solid ${C.gold}44` }}>
                    <div style={{ fontSize: 10, fontWeight: 700, color: C.gold, textTransform: "uppercase", letterSpacing: "0.1em", marginBottom: 6 }}>Answer</div>
                    <p style={{ fontSize: 13, color: "#333", lineHeight: 1.75, marginBottom: 12 }}>{item.a}</p>
                    <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
                      <span style={{ fontSize: 11, color: "#777" }}>Did you get it right?</span>
                      <button onClick={() => { setScores(s => ({ ...s, [qi]: true })); setRevealed(r => ({ ...r, [qi]: false })); }} style={{ padding: "4px 12px", borderRadius: 20, border: `1.5px solid ${C.green}`, background: mark === true ? C.green : "white", color: mark === true ? "white" : C.green, fontSize: 11, fontWeight: 700, cursor: "pointer" }}>✓ Yes</button>
                      <button onClick={() => { setScores(s => ({ ...s, [qi]: false })); setRevealed(r => ({ ...r, [qi]: false })); }} style={{ padding: "4px 12px", borderRadius: 20, border: `1.5px solid ${C.red}`, background: mark === false ? C.red : "white", color: mark === false ? "white" : C.red, fontSize: 11, fontWeight: 700, cursor: "pointer" }}>✗ Review again</button>
                      <button onClick={() => setRevealed(r => ({ ...r, [qi]: false }))} style={{ padding: "4px 12px", borderRadius: 20, border: "1.5px solid #ddd", background: "white", color: "#888", fontSize: 11, cursor: "pointer" }}>▲ Close</button>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

