// ─── AIRTABLE LOGGER ─────────────────────────────────────────────
const AIRTABLE_BASE_ID = "YOUR_BASE_ID";
const AIRTABLE_TABLE   = "Enrollments";
const AIRTABLE_API_KEY = "YOUR_AIRTABLE_API_KEY";

async function logToSheet(data) {
  try {
    await fetch(`https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/${AIRTABLE_TABLE}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${AIRTABLE_API_KEY}`,
      },
      body: JSON.stringify({ fields: data }),
    });
  } catch (e) {
    console.log("Airtable log attempted:", data);
  }
}

// ─── NAME ENTRY ──────────────────────────────────────────────────
function NameEntry({ onComplete }) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);

  const validate = () => {
    const e = {};
    if (name.trim().length < 2) e.name = "Please enter your full name.";
    if (!email.trim().match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) e.email = "Please enter a valid email address.";
    return e;
  };

  const handleSubmit = async () => {
    const e = validate();
    if (Object.keys(e).length > 0) { setErrors(e); return; }
    setSubmitting(true);
    await logToSheet({
      event: "enrollment",
      name: name.trim(),
      email: email.trim().toLowerCase(),
      date: new Date().toISOString(),
    });
    onComplete(name.trim(), email.trim().toLowerCase());
  };

  const ready = name.trim().length > 1 && email.trim().match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);

  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "2rem 0 1rem", textAlign: "center" }}>
      <img src={LOGO} alt="The Mukhlasin Diet" style={{ width: 140, height: "auto", borderRadius: 8, marginBottom: 16 }} />
      <div style={{ fontSize: 9, letterSpacing: "0.2em", textTransform: "uppercase", color: C.gold, marginBottom: 14 }}>The Mukhlasin Diet — 4th Edition</div>
      <div style={{ fontSize: 20, fontWeight: 600, fontFamily: "Georgia, serif", color: "#111", marginBottom: 8 }}>Welcome, student.</div>
      <div style={{ fontSize: 13, color: "#666", lineHeight: 1.75, maxWidth: 320, marginBottom: 24 }}>
        Please enter your name and email. Your name will appear on your Certificate of Completion. Your email will be used only to contact you about this course.
      </div>
      <div style={{ width: "100%", maxWidth: 320, textAlign: "left" }}>
        <label style={{ display: "block", fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.1em", color: C.gold, marginBottom: 6 }}>Your Full Name</label>
        <input type="text" value={name} onChange={e => { setName(e.target.value); setErrors(v => ({...v, name: ""})); }}
          onKeyDown={e => e.key === "Enter" && handleSubmit()}
          placeholder="Enter your full name"
          style={{ width: "100%", padding: "12px 16px", fontSize: 15, fontFamily: "Georgia, serif", border: `1.5px solid ${errors.name ? C.red : name.trim().length > 1 ? C.gold : "#ddd"}`, borderRadius: 10, outline: "none", color: "#111", background: "white", marginBottom: 4 }}
        />
        {errors.name && <div style={{ fontSize: 12, color: C.red, marginBottom: 8 }}>{errors.name}</div>}

        <label style={{ display: "block", fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.1em", color: C.gold, marginBottom: 6, marginTop: 14 }}>Email Address</label>
        <input type="email" value={email} onChange={e => { setEmail(e.target.value); setErrors(v => ({...v, email: ""})); }}
          onKeyDown={e => e.key === "Enter" && handleSubmit()}
          placeholder="Enter your email address"
          style={{ width: "100%", padding: "12px 16px", fontSize: 15, fontFamily: "sans-serif", border: `1.5px solid ${errors.email ? C.red : email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/) ? C.gold : "#ddd"}`, borderRadius: 10, outline: "none", color: "#111", background: "white", marginBottom: 4 }}
        />
        {errors.email && <div style={{ fontSize: 12, color: C.red, marginBottom: 8 }}>{errors.email}</div>}

        <button onClick={handleSubmit} disabled={submitting} style={{ width: "100%", padding: "13px", borderRadius: 10, background: ready && !submitting ? C.gold : "#ddd", color: ready && !submitting ? "white" : "#aaa", border: "none", fontSize: 14, fontWeight: 700, cursor: ready && !submitting ? "pointer" : "default", marginTop: 16 }}>
          {submitting ? "Starting..." : "Begin the Course →"}
        </button>

        <div style={{ marginTop: 14, fontSize: 11, color: "#aaa", lineHeight: 1.6, textAlign: "center" }}>
          Your email is stored securely and used only by the course instructor.
        </div>
      </div>
    </div>
  );
}

