// ─── ACCESS CONTROL ──────────────────────────────────────────────
// Free access codes — enter at the paywall email field
const FREE_CODES = ["SADAQAH", "ADMINTEST"];

// Check sessionStorage for active session (set by /magic-link page)
function checkSessionAccess() {
  try { return sessionStorage.getItem("ml_access") === "true"; }
  catch(e) { return false; }
}

// ─── PAYWALL SCREEN ──────────────────────────────────────────────
function PaywallScreen({ onUnlock }) {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState("idle"); // idle | sending | sent | error
  const [msg, setMsg] = useState("");

  const handleSubmit = async () => {
    const val = email.trim();
    // Check free codes
    if (FREE_CODES.includes(val.toUpperCase())) {
      try { sessionStorage.setItem("ml_access", "true"); } catch(e) {}
      onUnlock(val);
      return;
    }
    if (!val.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
      setMsg("Please enter a valid email address or access code.");
      return;
    }
    setStatus("sending");
    setMsg("");
    try {
      const res = await fetch("/api/send-magic-link", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: val }),
      });
      const data = await res.json();
      if (data.sent) {
        setStatus("sent");
        setMsg(`A magic link has been sent to ${val}. Check your inbox and click the link to enter the course.`);
      } else {
        setStatus("error");
        setMsg(data.error || "No purchase found for that email. Please use the email you paid with, or enroll below.");
      }
    } catch(e) {
      setStatus("error");
      setMsg("Connection error. Please try again.");
    }
  };

  return (
    <div style={{ display:"flex", flexDirection:"column", alignItems:"center", padding:"2rem 0 1rem", textAlign:"center" }}>
      <img src={LOGO} alt="The Mukhlasin Diet" style={{ width:120, height:"auto", borderRadius:8, marginBottom:16 }} />
      <div style={{ fontSize:9, letterSpacing:"0.2em", textTransform:"uppercase", color:C.gold, marginBottom:8 }}>The Mukhlasin Diet — 4th Edition</div>
      <div style={{ fontSize:20, fontWeight:600, fontFamily:"Georgia, serif", color:"#111", marginBottom:6 }}>Access the Course</div>
      <div style={{ fontSize:13, color:"#888", marginBottom:24, maxWidth:320 }}>
        Enter your email to receive a magic link — or enter your access code if you have one.
      </div>

      {status !== "sent" && (
        <>
          <input
            type="text"
            value={email}
            onChange={e => { setEmail(e.target.value); setMsg(""); }}
            placeholder="Your email or access code"
            style={{ width:"100%", maxWidth:320, padding:"12px 16px", fontSize:15, border:`1.5px solid ${C.gold}`, borderRadius:10, outline:"none", marginBottom:10, textAlign:"center" }}
            onKeyDown={e => e.key === "Enter" && handleSubmit()}
          />
          <button
            onClick={handleSubmit}
            disabled={status === "sending"}
            style={{ padding:"12px 32px", borderRadius:24, background:C.gold, color:"white", border:"none", fontSize:14, fontWeight:700, cursor:"pointer", marginBottom:16 }}
          >
            {status === "sending" ? "Sending…" : "Send Magic Link →"}
          </button>
        </>
      )}

      {msg && (
        <div style={{ fontSize:13, color: status === "error" ? "#c0392b" : C.green, maxWidth:320, lineHeight:1.7, marginBottom:16 }}>
          {msg}
        </div>
      )}

      {status !== "sent" && (
        <div style={{ marginTop:8, padding:"1.25rem", background:C.goldBg, borderRadius:12, maxWidth:320, width:"100%" }}>
          <div style={{ fontSize:11, color:C.muted, marginBottom:6, textTransform:"uppercase", letterSpacing:"0.1em" }}>Not enrolled yet?</div>
          <div style={{ fontSize:22, fontWeight:700, color:"#111", marginBottom:2 }}>$297</div>
          <div style={{ fontSize:11, color:C.muted, marginBottom:12 }}>Complete course · Certificate · Lifetime access</div>
          <a
            href="https://buy.stripe.com/00wbJ153D9Pg7D2a6a77O08"
            style={{ display:"block", padding:"11px 0", borderRadius:20, background:C.dark, color:C.gold, textDecoration:"none", fontSize:13, fontWeight:700, textAlign:"center" }}
          >
            Enroll Now — $297
          </a>
        </div>
      )}
    </div>
  );
}

export default function MukhlasinCourse() {
  const hasSession = checkSessionAccess();
  const [phase, setPhase] = useState(hasSession ? "protective" : "paywall"); // paywall | protective | name | welcome | course | certificate
  const [studentName, setStudentName] = useState("");
  const [studentEmail, setStudentEmail] = useState("");
  const [completionDate, setCompletionDate] = useState("");
  const [activeChapter, setActiveChapter] = useState(0);

  const sections = [...new Set(CHAPTERS.map(c => c.sec))];
  const [openSections, setOpenSections] = useState({ [CHAPTERS[0].sec]: true });
  const toggleSection = (sec) => setOpenSections(prev => ({ ...prev, [sec]: !prev[sec] }));

  return (
    <div style={{ maxWidth: 680, margin: "0 auto", fontFamily: "sans-serif", background: C.bg, minHeight: "100vh" }}>

      {/* Header */}
      <div style={{ background: C.dark, padding: "1rem 1.25rem", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div>
          <div style={{ fontSize: 9, letterSpacing: "0.18em", textTransform: "uppercase", color: C.gold, marginBottom: 3 }}>4th Edition · 2022</div>
          <div style={{ fontSize: 16, fontWeight: 700, color: C.cream, fontFamily: "Georgia, serif" }}>الْمُخْلَصِينَ — The Mukhlasin Diet</div>
        </div>
        {phase === "course" && (
          <div style={{ fontSize: 11, color: C.gold, textAlign: "right" }}>
            <div>Celebrating 30+ years</div>
            <div style={{ color: C.muted, fontSize: 10 }}>of fasting</div>
          </div>
        )}
      </div>

      {/* Body */}
      <div style={{ padding: "1.25rem" }}>
        {phase === "paywall" && <PaywallScreen onUnlock={(em) => { setStudentEmail(em); setPhase("protective"); }} />}
        {phase === "protective" && <ProtectiveSlides onComplete={() => setPhase("name")} />}
        {phase === "name" && <NameEntry onComplete={(name, email) => { setStudentName(name); setStudentEmail(email); setPhase("welcome"); }} />}
        {phase === "welcome" && <WelcomeViewer onComplete={() => setPhase("course")} />}
        {phase === "certificate" && <Certificate name={studentName} date={completionDate} onReturn={() => setPhase("course")} />}

        {phase === "course" && (
          <div>
            {/* Section navigator — collapsible */}
            <div style={{ marginBottom: 16, border: `0.5px solid ${C.border}`, borderRadius: 12, overflow: "hidden", background: "white" }}>
              {sections.map((sec, si) => {
                const isOpen = !!openSections[sec];
                const chaptersInSec = CHAPTERS.filter(c => c.sec === sec);
                const activeInSec = chaptersInSec.some(c => CHAPTERS.indexOf(c) === activeChapter);
                return (
                  <div key={sec}>
                    {/* Section header — tap to expand/collapse */}
                    <button
                      onClick={() => toggleSection(sec)}
                      style={{
                        width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between",
                        padding: "11px 14px", background: activeInSec ? C.goldBg : "white",
                        border: "none", borderTop: si > 0 ? `0.5px solid ${C.border}` : "none",
                        cursor: "pointer", textAlign: "left",
                      }}
                    >
                      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                        <div style={{ width: 6, height: 6, borderRadius: "50%", background: activeInSec ? C.gold : "#ccc" }} />
                        <span style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.1em", color: activeInSec ? C.gold : "#666" }}>{sec}</span>
                      </div>
                      <span style={{ fontSize: 13, color: C.gold, transform: isOpen ? "rotate(180deg)" : "none", transition: "transform 0.2s", display: "inline-block" }}>▾</span>
                    </button>

                    {/* Chapter buttons — revealed on expand */}
                    {isOpen && (
                      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, padding: "8px 14px 12px", borderTop: `0.5px solid ${C.border}`, background: C.goldBg }}>
                        {chaptersInSec.map(ch => {
                          const idx = CHAPTERS.indexOf(ch);
                          const isActive = activeChapter === idx;
                          return (
                            <button key={ch.id} onClick={() => setActiveChapter(idx)} style={{
                              fontSize: 10, padding: "5px 11px", borderRadius: 20, cursor: "pointer",
                              border: `1.5px solid ${isActive ? C.gold : "#d0c8bc"}`,
                              background: isActive ? C.gold : "white",
                              color: isActive ? "white" : "#555",
                              fontWeight: isActive ? 700 : 400,
                              whiteSpace: "nowrap",
                            }}>
                              {ch.label}
                            </button>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {/* Active chapter */}
            <div style={{ background: "white", borderRadius: 12, padding: "1.25rem", border: `0.5px solid ${C.border}` }}>
              <div style={{ marginBottom: 14 }}>
                <div style={{ fontSize: 11, color: C.gold, textTransform: "uppercase", letterSpacing: "0.1em", marginBottom: 4 }}>{CHAPTERS[activeChapter].sec}</div>
                <div style={{ fontSize: 18, fontWeight: 700, fontFamily: "Georgia, serif", color: "#111" }}>{CHAPTERS[activeChapter].label}</div>
              </div>
              <ChapterViewer key={activeChapter} chapter={CHAPTERS[activeChapter]} />
            </div>

            {/* Nav arrows */}
            <div style={{ display: "flex", justifyContent: "space-between", marginTop: 14 }}>
              <button onClick={() => setActiveChapter(i => Math.max(0, i - 1))} disabled={activeChapter === 0} style={{ padding: "8px 16px", borderRadius: 20, border: `0.5px solid ${C.border}`, background: "white", cursor: activeChapter === 0 ? "not-allowed" : "pointer", fontSize: 12, color: activeChapter === 0 ? "#ccc" : "#444" }}>← Previous</button>
              {activeChapter < CHAPTERS.length - 1
                ? <button onClick={() => setActiveChapter(i => i + 1)} style={{ padding: "8px 16px", borderRadius: 20, border: `0.5px solid ${C.border}`, background: C.gold, cursor: "pointer", fontSize: 12, color: "white", fontWeight: 700 }}>Next Chapter →</button>
                : <button onClick={async () => {
                    const date = new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
                    setCompletionDate(date);
                    await logToSheet({ event: "completion", name: studentName, email: studentEmail, date: new Date().toISOString() });
                    setPhase("certificate");
                  }} style={{ padding: "10px 22px", borderRadius: 20, background: C.gold, border: "none", cursor: "pointer", fontSize: 13, color: "white", fontWeight: 700, boxShadow: `0 2px 12px ${C.gold}55` }}>✦ Complete the Course</button>
              }
            </div>

            {/* Footer */}
            <div style={{ textAlign: "center", marginTop: "2rem", padding: "1.25rem", background: C.goldBg, borderRadius: 12 }}>
              <div style={{ fontSize: 13, color: C.gold, lineHeight: 1.7, fontFamily: "Georgia, serif", fontStyle: "italic" }}>
                "The only way to repay this blessing is to help another person accept their own — and be themselves."
              </div>
              <div style={{ fontSize: 11, color: "#aaa", marginTop: 6 }}>— Amin Shabazz Muhammad · The Mukhlasin Diet, 4th Edition</div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
